#!/usr/bin/env python3

"""
Raspberry Pi ADS1x15 16-Bit ADC Demo

This script demonstrates reading analog values from four ADS1x15 analog inputs
connected to the Raspberry Pi using the I2C interface. It uses the
Adafruit_ADS1x15 library to interface with the ADC.

Author: Jan Lipovský <janlipovsky@gmail.com>, janlipovsky.cz
Modified by: Bard
"""

import time
import sys
import smbus
from Adafruit_ADS1x15 import ADS1015, ADS1115, ADS1315

# Constants
I2C_BUS = 1  # I2C bus number on Raspberry Pi
NUM_CHANNELS = 4  # Number of ADC channels to read
DATA_RATE = 128  # ADC data rate in samples per second
FULL_SCALE_VOLTAGE = 4.096  # Full-scale voltage range for the ADC
PGA_GAIN = 1  # Programmable gain amplifier gain setting
TIMEOUT_MS = 100  # Timeout in milliseconds for ADC conversion

# Initialize I2C bus
try:
    bus = smbus.SMBus(I2C_BUS)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    sys.exit(1)


def read_adc_channel(channel, adc_type):
    """
    Reads the analog value from the specified ADC channel.

    Args:
        channel (int): The ADC channel number (0-3).
        adc_type (str): The type of ADC (ADS1015, ADS1115, or ADS1315).

    Returns:
        int: The raw ADC value (16-bit integer), or None on error.
    """
    if channel < 0 or channel > 3:
        print(f"Invalid ADC channel: {channel}. Must be between 0 and 3.")
        return None

    if adc_type not in ('ADS1015', 'ADS1115', 'ADS1315'):
        print(f"Invalid ADC type: {adc_type}. Must be ADS1015, ADS1115, or ADS1315.")
        return None

    try:
        if adc_type == 'ADS1015':
            adc = ADS1015(address=0x48, busnum=I2C_BUS)
        elif adc_type == 'ADS1115':
            adc = ADS1115(address=0x48, busnum=I2C_BUS)
        elif adc_type == 'ADS1315':
            adc = ADS1315(address=0x48, busnum=I2C_BUS)

        # Configure the ADC
        config = {
            'ADS1015': {
                'MUX': {
                    0: 'AIN0',
                    1: 'AIN1',
                    2: 'AIN2',
                    3: 'AIN3'
                },
                'PGA': {
                    1: '±6.144V',
                    2: '±4.096V',
                    4: '±2.048V',
                    8: '±1.024V',
                    16: '±0.512V'
                },
                'MODE': {
                    0: 'Single-shot',
                    1: 'Continuous'
                },
                'DR': {
                    128: '128SPS',
                    250: '250SPS',
                    490: '490SPS',
                    920: '920SPS'
                },
                'COMP_MODE': {
                    0: 'Traditional comparator',
                    1: 'Window comparator'
                },
                'COMP_POL': {
                    0: 'Active low',
                    1: 'Active high'
                },
                'COMP_LAT': {
                    0: 'Non-latching',
                    1: 'Latching'
                },
                'COMP_QUE': {
                    0: 'Disable',
                    1: '1 conversion',
                    2: '2 conversions',
                    3: '4 conversions'
                }
            },
            'ADS1115': {
                'MUX': {
                    0: 'AIN0_GND',
                    1: 'AIN1_GND',
                    2: 'AIN2_GND',
                    3: 'AIN3_GND',
                    4: 'AIN0_VDD',
                    5: 'AIN1_VDD',
                    6: 'AIN2_VDD',
                    7: 'AIN3_VDD'
                },
                'PGA': {
                    6: '±6.144V',
                    4: '±4.096V',
                    2: '±2.048V',
                    1: '±1.024V',
                    0.5: '±0.512V',
                    0.25: '±0.256V'
                },
                'MODE': {
                    0: 'Single-shot',
                    1: 'Continuous'
                },
                'DR': {
                    250: '250SPS',
                    475: '475SPS',
                    950: '950SPS',
                    1660: '1660SPS',
                    2475: '2475SPS',
                    3330: '3330SPS'
                },
                'COMP_MODE': {
                    0: 'Traditional comparator',
                    1: 'Window comparator'
                },
                'COMP_POL': {
                    0: 'Active low',
                    1: 'Active high'
                },
                'COMP_LAT': {
                    0: 'Non-latching',
                    1: 'Latching'
                },
                'COMP_QUE': {
                    0: 'Disable',
                    1: '1 conversion',
                    2: '2 conversions',
                    3: '4 conversions'
                }
            },
            'ADS1315': {
                'MUX': {
                    0: 'AIN0_GND',
                    1: 'AIN1_GND',
                    2: 'AIN2_GND',
                    3: 'AIN3_GND',
                    4: 'AIN0_VDD',
                    5: 'AIN1_VDD',
                    6: 'AIN2_VDD',
                    7: 'AIN3_VDD'
                },
                'PGA': {
                    6: '±6.144V',
                    4: '±4.096V',
                    2: '±2.048V',
                    1: '±1.024V',
                    0.5: '±0.512V',
                    0.25: '±0.256V'
                },
                'MODE': {
                    0: 'Single-shot',
                    1: 'Continuous'
                },
                'DR': {
                    250: '250SPS',
                    475: '475SPS',
                    950: '950SPS',
                    1660: '1660SPS',
                    2475: '2475SPS',
                    3330: '3330SPS'
                },
                'COMP_MODE': {
                    0: 'Traditional comparator',
                    1: 'Window comparator'
                },
                'COMP_POL': {
                    0: 'Active low',
                    1: 'Active high'
                },
                'COMP_LAT': {
                    0: 'Non-latching',
                    1: 'Latching'
                },
                'COMP_QUE': {
                    0: 'Disable',
                    1: '1 conversion',
                    2: '2 conversions',
                    3: '4 conversions'
                }
            }
        }

        # Construct configuration string
        config_string = (
            'C0=' + str(config[adc_type]['COMP_QUE'][0]) +
            '|C1=' + str(config[adc_type]['COMP_LAT'][0]) +
            '|C2=' + str(config[adc_type]['COMP_POL'][0]) +
            '|C3=' + str(config[adc_type]['COMP_MODE'][0]) +
            '|M0=' + str(config[adc_type]['MUX'][channel]) +
            '|M1=' + str(config[adc_type]['PGA'][PGA_GAIN]) +
            '|M2=' + str(config[adc_type]['MODE'][0]) +
            '|M3=' + str(config[adc_type]['DR'][DATA_RATE]) +
            '|P0=' + str(config[adc_type]['COMP_QUE'][0]) +
            '|P1=' + str(config[adc_type]['COMP_LAT'][0]) +
            '|P2=' + str(config[adc_type]['COMP_POL'][0]) +
            '|P3=' + str(config[adc_type]['COMP_MODE'][0])
        )

        # Trigger the conversion
        bus.write_i2c_block_data(0x48, 0x01, [0x80 | (channel & 0x03), 0xE0 | ((config[adc_type]['DR'][DATA_RATE] - 1) << 3), 0x00])

        # Wait for conversion to complete
        start_time = time.time()
        while True:
            status = bus.read_byte_data(0x48, 0x00)
            if (status & 0x80) == 0:
                break
            if time.time() - start_time > TIMEOUT_MS / 1000.0:
                print(f"Timeout waiting for ADC {channel} conversion.")
                return None

        # Read the conversion result
        result = bus.read_i2c_block_data(0x48, 0x00, 2)
        raw_value = (result[0] << 8) | result[1]

        # Convert to signed value
        if raw_value > 32767:
            raw_value -= 65536

        return raw_value

    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None


def main():
    """
    Main function to read and print ADC values.
    """
    try:
        while True:
            adc_values = []
            for i in range(NUM_CHANNELS):
                value = read_adc_channel(i, 'ADS1015')
                if value is not None:
                    adc_values.append(value)
                else:
                    adc_values.append(None)  # Append None to indicate an error

            print(f"ADC Values: {adc_values}")
            time.sleep(0.5)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        bus.close()  # Close the I2C bus
        print("I2C bus closed.")


if __name__ == "__main__":
    main()

