import picamera
import picamera.array
import numpy as np
import time

# Configuration
CAMERA_RESOLUTION = (640, 480)
MOTION_THRESHOLD = 10
CAPTURE_INTERVAL = 2  # seconds
WARM_UP_TIME = 2  # seconds

def initialize_camera():
    """Initializes the Raspberry Pi camera."""
    try:
        camera = picamera.PiCamera()
        camera.resolution = CAMERA_RESOLUTION
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the camera and returns it as a NumPy array."""
    try:
        with picamera.array.PiRGBArray(camera) as output:
            camera.capture(output, 'rgb')
            return output.array
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def calculate_average_pixel_value(frame):
    """Calculates the average pixel value of a NumPy array."""
    try:
        return np.mean(frame)
    except Exception as e:
        print(f"Error calculating average pixel value: {e}")
        return 0

def detect_motion(current_average, baseline_average, threshold):
    """Detects motion by comparing the current average to the baseline average."""
    try:
        return abs(current_average - baseline_average) > threshold
    except Exception as e:
        print(f"Error detecting motion: {e}")
        return False

def save_motion_detected_frame(frame):
    """Saves the current frame as a motion.jpg file."""
    try:
        with picamera.PiCamera() as camera:
            camera.resolution = CAMERA_RESOLUTION
            camera.capture('motion.jpg')
    except Exception as e:
        print(f"Error saving motion detected frame: {e}")

def main():
    """Main function to run the motion detection system."""
    camera = initialize_camera()
    if camera is None:
        return

    baseline_average = 0.0
    try:
        # Warm up the camera
        print("Warming up camera...")
        time.sleep(WARM_UP_TIME)

        # Main loop for motion detection
        print("Starting motion detection...")
        for _ in range(10):  # Example: Capture 10 frames
            frame = capture_frame(camera)
            if frame is None:
                continue

            current_average = calculate_average_pixel_value(frame)

            if detect_motion(current_average, baseline_average, MOTION_THRESHOLD):
                print("Motion detected!")
                save_motion_detected_frame(frame)
                baseline_average = current_average  # Update baseline

            time.sleep(CAPTURE_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        # Ensure camera resources are released
        if camera:
            camera.close()
            print("Camera resources released.")

if __name__ == "__main__":
    main()

