import serial
import time
import contextlib

# Bluetooth serial port configuration
BLUETOOTH_PORT = '/dev/rfcomm4'
BLUETOOTH_BAUD_RATE = 38400
BLUETOOTH_TIMEOUT = 1

# Context manager for serial port handling
@contextlib.contextmanager
def bluetooth_serial_port(port, baudrate, timeout):
    """Context manager for opening and closing a Bluetooth serial port."""
    try:
        bluetooth_port = serial.Serial(port, baudrate, timeout=timeout)
        yield bluetooth_port
    finally:
        if bluetooth_port and bluetooth_port.is_open:
            bluetooth_port.close()

def send_message(bluetooth_port, message):
    """Sends a message over the Bluetooth serial port."""
    try:
        # Encode the message as UTF-8 and prepend a 'X' for identification
        encoded_message = f'X{message}\n'.encode('utf-8')
        bluetooth_port.write(encoded_message)
        return True
    except serial.SerialException as serial_error:
        print(f"Serial communication error: {serial_error}")
        return False
    except Exception as general_error:
        print(f"An unexpected error occurred: {general_error}")
        return False

def main():
    """Main function to handle user input and send messages."""
    try:
        # Open the Bluetooth serial port
        with bluetooth_serial_port(BLUETOOTH_PORT, BLUETOOTH_BAUD_RATE, BLUETOOTH_TIMEOUT) as bluetooth_port:
            print(f"Connected to Bluetooth port: {BLUETOOTH_PORT}")

            while True:
                try:
                    # Get user input
                    user_input = input('Enter message (or type "q" to quit): ')

                    # Exit if the user enters 'q'
                    if user_input.lower() == 'q':
                        break

                    # Send the message
                    if send_message(bluetooth_port, user_input):
                        print(f"Sent: {user_input}")
                    else:
                        print("Failed to send message.")

                except KeyboardInterrupt:
                    print("\nExiting program.")
                    break
                except Exception as error:
                    print(f"An unexpected error occurred: {error}")

    except serial.SerialException as e:
        print(f"Error opening Bluetooth port: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

