        return decoded_objects
    except Exception as e:
        log_error(f"QR code decoding failed: {e}")
        return None

def validate_data(data):
    """Validates the decoded data."""
    if not data:
        return False
    if not all(c.isalpha() or c.isdigit() for c in data):
        return False
    return True

def log_data(camera_id, item_id, timestamp):
    """Logs the data to the CSV file."""
    try:
