import io
import numpy as np
from picamera2 import Picamera2

class CameraStreamBuffer:
    def __init__(self, c):
        self.c = c
        self.b = io.BytesIO()
        self.f = False

    def write(self, d):
        if d.startswith(b'\xff\xd8'):
            self.b.seek(0)
            self.f = True
            return self.c.imdecode(self.b.read())
        if d.startswith(b'\xff\xd9'):
            self.f = False
            self.b.seek(0)
            return self.b.read()
        self.b.write(d)
        return None

class MotionDetectionBuffer:
    def __init__(self, f):
        self.f = f

    def write(self, d):
        if d.startswith(b'\xff\xd8'):
            self.b = io.BytesIO()
            self.t = 0
            self.h = 0
        if d.startswith(b'\xff\xd9'):
            self.b.seek(0)
            d = self.b.read()
            self.b.seek(0)
            self.b.truncate()
            if self.t > 0:
                try:
                    a = self.c.imdecode(d)
                    self.f(a, self.c.imdecode(d))
                except:
                    pass
            self.t += 1
        self.b.write(d)
        return len(d)

