#!/usr/bin/env python3

"""
A driver for the Aosong DHT20 temperature and humidity sensor using the Adafruit_DHT library.

This module provides a robust and optimized implementation for reading temperature and humidity data
from the DHT20 sensor using a functional approach with comprehensive error handling, performance
optimizations, and best practices for hardware interaction.
"""

import time
import logging
from functools import partial
from typing import Tuple, Optional

try:
    import smbus
except ImportError:
    logging.warning("smbus not found.  I2C communication will be disabled.")
    smbus = None

from Adafruit_DHT import DHT20, DHTError

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DEFAULT_I2C_BUS = 1
DEFAULT_RETRY_COUNT = 5
DEFAULT_RETRY_DELAY = 0.01  # seconds
MAX_MEASUREMENT_ATTEMPTS = 10
MEASUREMENT_INTERVAL = 2  # seconds
CRC_CHECK_ATTEMPTS = 5

# Type aliases
I2CDevice = Optional[smbus.SMBus]
Temperature = Optional[float]
Humidity = Optional[float]
Error = Optional[DHTError]


def _calculate_crc8(data: bytes) -> int:
    """Calculates the CRC-8 checksum."""
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = (crc << 1) ^ 0x31
            else:
                crc = crc << 1
    return crc & 0xFF


def _read_register(device: I2CDevice, register: int, length: int) -> Optional[bytes]:
    """Reads data from the specified register with error handling."""
    if device is None:
        logger.error("I2C device not initialized.")
        return None
    try:
        return device.read_i2c_block_data(DHT20.ADDRESS, register, length)
    except OSError as e:
        logger.error(f"I2C read error: {e}")
        return None


def _write_register(device: I2CDevice, register: int, data: bytes) -> None:
    """Writes data to the specified register with error handling."""
    if device is None:
        logger.error("I2C device not initialized.")
        return
    try:
        device.write_i2c_block_data(DHT20.ADDRESS, register, data)
    except OSError as e:
        logger.error(f"I2C write error: {e}")


def _wait_for_sensor_ready(device: I2CDevice) -> bool:
    """Waits for the sensor to become ready with error handling."""
    if device is None:
        logger.error("I2C device not initialized.")
        return False
    for _ in range(20):  # Check 20 times with 0.5s delay
        status = _read_register(device, DHT20.STATUS_REG, 1)
        if status is None:
            return False
        if (status[0] & 0x80) == 0:
            return True
        time.sleep(0.5)
    logger.warning("Sensor not ready after multiple retries.")
    return False


def _measure_temperature_and_humidity(device: I2CDevice) -> Tuple[Temperature, Humidity, Error]:
    """Measures temperature and humidity with error handling and retries."""
    if device is None:
        logger.error("I2C device not initialized.")
        return None, None, DHTError("I2C device not initialized")

    for attempt in range(MAX_MEASUREMENT_ATTEMPTS):
        if not _wait_for_sensor_ready(device):
            return None, None, DHTError("Sensor not ready")

        _write_register(device, DHT20.MEASURE_REG, [0x33, 0x00])  # Start measurement

        for _ in range(CRC_CHECK_ATTEMPTS):
            status = _read_register(device, DHT20.STATUS_REG, 1)
            if status is None:
                return None, None, DHTError("I2C read error")
            if (status[0] & 0x80) == 0:
                break
            time.sleep(0.01)  # Wait for measurement to complete

        data = _read_register(device, DHT20.DATA_REG, 7)
        if data is None:
            return None, None, DHTError("I2C read error")

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        temperature = temperature_raw / 5242.88 - 50.0
        humidity = humidity_raw / 0x10000 * 100.0

        crc = _calculate_crc8(data[:6])
        if crc != data[6]:
            logger.warning(f"CRC error detected on attempt {attempt + 1}. Retrying...")
            continue

        return temperature, humidity, None

    logger.error("Failed to read valid data after multiple retries.")
    return None, None, DHTError("Failed to read valid data after multiple retries")


def get_temperature_and_humidity(sensor: DHT20, device: I2CDevice = None) -> Tuple[Temperature, Humidity, Error]:
    """
    Gets the latest temperature and humidity readings from the DHT20 sensor.

    Args:
        sensor: The DHT20 sensor type.
        device: The I2C device object. If None, the default I2C bus is used.

    Returns:
        A tuple containing the temperature (in Celsius) and humidity (in percentage),
        or (None, None, DHTError("Failed to read sensor data")) if an error occurs.
    """
    if device is None and smbus is None:
        logger.error("smbus not available. Cannot initialize I2C device.")
        return None, None, DHTError("smbus not available")

    device = device or smbus.SMBus(DEFAULT_I2C_BUS)

    if sensor != DHT20:
        logger.warning(f"Unsupported sensor type: {sensor}. Using DHT20.")
        sensor = DHT20

    if sensor != DHT20:
        logger.error(f"Unsupported sensor type: {sensor}")
        return None, None, DHTError(f"Unsupported sensor type: {sensor}")

    if device is None:
        logger.error("I2C device not initialized.")
        return None, None, DHTError("I2C device not initialized")

    last_read_time = time.time()
    while time.time() - last_read_time < MEASUREMENT_INTERVAL:
        temperature, humidity, error = _measure_temperature_and_humidity(device)
        if error is None:
            return temperature, humidity, None
        time.sleep(DEFAULT_RETRY_DELAY)

    logger.warning("Measurement interval exceeded. Returning cached values or None if available.")
    return None, None, DHTError("Measurement interval exceeded")


