# AHT20 Temperature and Humidity Sensor Demo for Raspberry Pi 5
# Reads temperature and humidity from an AHT20 sensor connected via I2C.
# Designed for STEM education.

import time
import board
import busio
import adafruit_ahtx0

# Constants
I2C_RETRY_DELAY = 5  # seconds
TEMPERATURE_MIN = -40  # °C
TEMPERATURE_MAX = 85  # °C
HUMIDITY_MIN = 0  # %
HUMIDITY_MAX = 100  # %

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the AHT20 sensor."""
    try:
        sensor = adafruit_ahtx0.AHTx0(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error initializing AHT20 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Reads temperature and humidity from the sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.relative_humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def validate_data(temperature, humidity):
    """Validates temperature and humidity readings."""
    if temperature is not None and (temperature < TEMPERATURE_MIN or temperature > TEMPERATURE_MAX):
        print(f"Error: Temperature out of range: {temperature:.1f} °C")
        return False
    if humidity is not None and (humidity < HUMIDITY_MIN or humidity > HUMIDITY_MAX):
        print(f"Error: Humidity out of range: {humidity:.1f} %")
        return False
    return True

def display_data(temperature, humidity):
    """Displays the temperature and humidity readings."""
    print(f"Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")

def main():
    """Main function to read and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("Failed to initialize I2C. Exiting.")
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        print("Failed to initialize AHT20 sensor. Exiting.")
        i2c_bus.deinit()
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(sensor)

            if temperature is not None and humidity is not None:
                if validate_data(temperature, humidity):
                    display_data(temperature, humidity)
                else:
                    print("Invalid data received. Retrying...")
            else:
                print("Failed to read sensor data. Retrying...")

            time.sleep(5)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        print("Shutting down...")
        i2c_bus.deinit()
        print("I2C resources released.")

if __name__ == "__main__":
    main()

