# uart_temp_humidity_alert_rpi.py
# Reads temperature and humidity from a UART sensor and triggers alerts.
# Designed for a Raspberry Pi 4 Model B in an industrial automation context.

import serial
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# UART configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Temperature and humidity thresholds
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def initialize_uart(port, baudrate, timeout):
    """Initializes the UART connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        logging.info(f"UART connection established on {port} at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Failed to initialize UART: {e}")
        return None

def read_sensor_data(serial_connection):
    """Reads temperature and humidity data from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            temperature, humidity = line.split(',')
            return float(temperature), float(humidity)
        else:
            return None, None
    except ValueError as e:
        logging.error(f"Invalid data format: {e}")
        return None, None
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if temperature or humidity exceeds the defined thresholds."""
    if temperature is not None and temperature > TEMPERATURE_THRESHOLD:
        logging.warning(f"Temperature exceeds threshold: {temperature:.1f}°C")
    if humidity is not None and humidity > HUMIDITY_THRESHOLD:
        logging.warning(f"Humidity exceeds threshold: {humidity:.1f}%")

def main():
    """Main function to read sensor data and trigger alerts."""
    uart_connection = initialize_uart(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if uart_connection is None:
        logging.error("Failed to initialize UART. Exiting.")
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(uart_connection)

            if temperature is not None and humidity is not None:
                logging.info(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                check_thresholds(temperature, humidity)

            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")

    finally:
        if uart_connection and uart_connection.is_open:
            uart_connection.close()
            logging.info("UART connection closed.")

if __name__ == "__main__":
    main()

