# uart_temp_humidity_alert_rpi.py
# Reads temperature and humidity from a UART sensor and triggers alerts on Raspberry Pi

import serial
import time

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
SLEEP_INTERVAL = 1  # seconds

def read_sensor_data(serial_port):
    """Reads temperature and humidity data from the serial port."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        if data:
            temperature, humidity = data.split(',')
            return float(temperature), float(humidity)
        return None, None
    except ValueError:
        print("Error: Invalid data received from sensor.")
        return None, None
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if temperature or humidity exceeds predefined thresholds."""
    if temperature is not None and temperature > TEMPERATURE_THRESHOLD:
        print(f"Alert: Temperature exceeds threshold: {temperature:.1f}°C")
    if humidity is not None and humidity > HUMIDITY_THRESHOLD:
        print(f"Alert: Humidity exceeds threshold: {humidity:.1f}%")

def main():
    """Main function to read sensor data and trigger alerts."""
    try:
        # Initialize serial port
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1) as ser:
            print(f"Connected to serial port {SERIAL_PORT}")

            while True:
                temperature, humidity = read_sensor_data(ser)

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                    check_thresholds(temperature, humidity)

                time.sleep(SLEEP_INTERVAL)

    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        print("Exiting program.")

if __name__ == "__main__":
    main()

