import DOGProtocol as DOG  # Assuming this is a custom module for DOG communication
import time
import threading
import os
import signal
import sys

# Constants
LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # seconds

# Global flag to control the main loop
running = True

# Function to handle program termination signals
def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    print("Shutting down...")
    running = False
    # Clean up resources here (if needed)
    sys.exit(0)

# Register the signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to create the log file
def create_log_file(filename):
    """Creates a new log file with the given name."""
    try:
        with open(filename, "w") as f:
            print(f"Created log file: {filename}")
    except IOError as e:
        print(f"Error creating log file: {e}")
        sys.exit(1)

# Function to start the data logging thread
def start_logging(filename):
    """Starts a background thread to continuously log data."""
    global running
    try:
        create_log_file(filename)
        print(f"Logging started to: {filename}")
        while running:
            try:
                data = DOG.receive()  # Get data from DOG
                if data:
                    log_data(filename, data)  # Log the data
            except Exception as e:
                print(f"Error receiving data: {e}")
                break  # Exit the loop on error
            time.sleep(POLL_INTERVAL)  # Wait before the next poll
    except Exception as e:
        print(f"Error starting logging: {e}")
    finally:
        stop_logging()  # Ensure cleanup on exit

# Function to stop the data logging thread
def stop_logging():
    """Stops the data logging thread and cleans up resources."""
    global running
    print("Stopping logging...")
    running = False  # Set the flag to stop the loop
    # Add any necessary cleanup here (e.g., closing file handles)
    print("Logging stopped.")

# Function to log data to the file
def log_data(filename, data):
    """Appends the given data to the log file with a newline."""
    try:
        with open(filename, "a") as f:
            f.write(data + "\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")

# Function to display the contents of the log file
def display_log_file(filename):
    """Displays the contents of the log file."""
    try:
        with open(filename, "r") as f:
            print(f.read())
    except IOError as e:
        print(f"Error reading log file: {e}")

# Function to send data using DOG
def send_data(data):
    """Sends the given data using the DOG protocol."""
    try:
        DOG.send(data)
        print(f"Sent data: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

# Function to write data directly to the log file
def write_to_log(data):
    """Writes the given data directly to the log file."""
    log_data(LOG_FILE, data)

# Main function
def main():
    """Main function to handle command-line interface."""
    global running

    # Parse command-line arguments
    if len(sys.argv) > 1:
        command = sys.argv[1].lower()
        if command == "start":
            if len(sys.argv) == 3:
                filename = sys.argv[2]
                start_logging(filename)
            else:
                print("Usage: start <filename>")
        elif command == "stop":
            stop_logging()
        elif command == "help":
            if len(sys.argv) == 2:
                print("Available commands:")
                print("  start <filename>")
                print("  stop")
                print("  help")
                print("  display")
                print("  send <data>")
                print("  write <data>")
                print("  exit")
            else:
                command = sys.argv[2].lower()
                if command == "start":
                    print("Usage: start <filename>")
                elif command == "stop":
                    print("Usage: stop")
                elif command == "help":
                    print("Usage: help")
                elif command == "display":
                    print("Usage: display")
                elif command == "send":
                    print("Usage: send <data>")
                elif command == "write":
                    print("Usage: write <data>")
                elif command == "exit":
                    print("Usage: exit")
        elif command == "display":
            display_log_file(LOG_FILE)
        elif command == "send":
            if len(sys.argv) == 3:
                data = sys.argv[2]
                send_data(data)
            else:
                print("Usage: send <data>")
        elif command == "write":
            if len(sys.argv) == 3:
                data = sys.argv[2]
                write_to_log(data)
            else:
                print("Usage: write <data>")
        elif command == "exit":
            stop_logging()
            sys.exit(0)
        else:
            print("Invalid command. Use 'help' for available commands.")
    else:
        print("Usage: start <filename>")

# Run the main function
if __name__ == "__main__":
    main()

