def get_gpio_num(model):
    """
    Determines the number of GPIO pins available based on the Raspberry Pi model.

    Args:
        model (str): The Raspberry Pi model name.

    Returns:
        int: The number of GPIO pins.
    """
    if model == 'Model B':
        return 17
    elif model == 'Model B+':
        return 26
    else:
        return 17  # Default to 17 if model is unknown

def parse_arguments():
    """
    Parses command-line arguments.

    Returns:
        argparse.Namespace: An object containing the parsed arguments.
    """
    parser = argparse.ArgumentParser(description='Automated GPIO control for Raspberry Pi.')
    parser.add_argument('-d', '--debounce', type=int, default=DEFAULT_DEBOUNCE_MS,
                        help='Debounce time in milliseconds (default: 200ms)')
    parser.add_argument('-l', '--log-level', type=str, default='INFO',
                        choices=['DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL'],
                        help='Logging level (default: INFO)')
    parser.add_argument('-m', '--monitor', action='store_true',
                        help='Enable monitoring mode (log all state changes)')
    parser.add_argument('-p', '--poll-interval', type=int, default=1,
                        help='Poll interval in seconds (default: 1 second)')
    parser.add_argument('-r', '--reset', action='store_true',
                        help='Reset the state of all GPIO pins to their default state')
    parser.add_argument('-s', '--state-file', type=str, default='gpio_state.json',
                        help='Path to the JSON file to store the GPIO state (default: gpio_state.json)')
    parser.add_argument('-v', '--verbose', action='store_true',
                        help='Enable verbose output (print pin numbers and values)')
    return parser.parse_args()

def setup_gpio(gpio_ch, debounce_ms):
    """
    Sets up the GPIO pins as input or output with debouncing.

    Args:
        gpio_ch (list): A list of GPIO pin objects.
        debounce_ms (int): The debounce time in milliseconds.
    """
    for pin in gpio_ch:
        try:
            if pin.is_input:
                pin.when_pressed = None
                pin.when_released = None
            else:
                pin.when_pressed = lambda: record_state(pin, gpio_ch, debounce_ms)
                pin.when_released = lambda: record_state(pin, gpio_ch, debounce_ms)
            logger.debug(f"GPIO {pin.pin} set up for input with debounce {debounce_ms}ms")
        except Exception as e:
            logger.error(f"Error setting up GPIO {pin.pin}: {e}")
            raise RuntimeError(f"Failed to setup GPIO {pin.pin}: {e}")

def record_state(pin, gpio_ch, debounce_ms):
    """
    Records the current state of a GPIO pin and updates the log file.

    Args:
        pin (InputDevice): The GPIO pin object.
        gpio_ch (list): A list of GPIO pin objects.
        debounce_ms (int): The debounce time in milliseconds.
    """
    try:
        state = pin.value
        timestamp = time.time()
        log_entry = {
            'timestamp': timestamp,
            'pin_number': pin.pin,
            'state': state,
            'debounce_ms': debounce_ms
        }
        with open(args.state_file, 'a') as f:
            json.dump(log_entry, f)
            f.write('\n')
        if args.monitor:
            logger.info(f"GPIO {pin.pin} changed to {state} (debounce {debounce_ms}ms)")
    except Exception as e:
        logger.error(f"Error recording state for GPIO {pin.pin}: {e}")

def load_state(state_file):
    """
    Loads the state of the GPIO pins from a JSON file.

    Args:
        state_file (str): The path to the JSON file.

    Returns:
        list: A list of GPIO pin objects with their states loaded.
    """
    try:
        gpio_ch = []
        if os.path.exists(state_file):
            with open(state_file, 'r') as f:
                for line in f:
                    try:
                        entry = json.loads(line.strip())
                        if entry['pin_number'] not in [pin.pin for pin in gpio_ch]:
                            gpio_ch.append(InputDevice(entry['pin_number'], pull_up_down=InputDevice.PULL_UP_DOWN_OFF))
                        pin = gpio_ch[entry['pin_number']]
                        pin.value = entry['state']
                        logger.debug(f"Loaded GPIO {pin.pin} from state file: {entry['state']}")
                    except json.JSONDecodeError as e:
                        logger.warning(f"Error decoding JSON from state file: {e}")
                        continue
        else:
            logger.warning(f"State file not found: {state_file}")

        return gpio_ch
    except FileNotFoundError:
        logger.warning(f"State file not found: {state_file}")
        return []
    except Exception as e:
        logger.error(f"Error loading state from file: {e}")
        return []

def cleanup_gpio(gpio_ch):
    """
    Cleans up the GPIO pins by setting them to input mode.

    Args:
        gpio_ch (list): A list of GPIO pin objects.
    """
    try:
        for pin in gpio_ch:
            pin.when_pressed = None
            pin.when_released = None
            pin.mode = InputDevice.IN
            logger.debug(f"GPIO {pin.pin} cleaned up")
    except Exception as e:
        logger.error(f"Error cleaning up GPIO {pin.pin}: {e}")

def main():
    """
    Main function to run the automated GPIO control system.
    """
    global args

    args = parse_arguments()

    # Configure logging
    logging.getLogger().setLevel(args.log_level)
    handler = logging.StreamHandler()
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)
    logging.getLogger().addHandler(handler)

    logger.info("Starting automated GPIO control system...")
    logger.info(f"Logging level: {args.log_level}")
    logger.info(f"Debounce time: {args.debounce}ms")
    logger.info(f"Poll interval: {args.poll_interval}s")
    logger.info(f"State file: {args.state_file}")
    logger.info(f"Verbose output: {args.verbose}")

    model = get_raspi_model()
    gpio_num = get_gpio_num(model)
    logger.info(f"Detected Raspberry Pi model: {model}, GPIO count: {gpio_num}")

    gpio_ch = []
    try:
        gpio_ch = [InputDevice(pin_num, pull_up_down=InputDevice.PULL_UP_DOWN_OFF) for pin_num in range(gpio_num)]
    except Exception as e:
        logger.error(f"Error initializing GPIO pins: {e}")
        sys.exit(1)

    if args.reset:
        logger.info("Resetting GPIO state...")
        cleanup_gpio(gpio_ch)
        gpio_ch = load_state(args.state_file)
        if not gpio_ch:
            logger.warning("No GPIO pins loaded after reset. Using default state.")
            gpio_ch = [InputDevice(pin_num, pull_up_down=InputDevice.PULL_UP_DOWN_OFF) for pin_num in range(gpio_num)]

    setup_gpio(gpio_ch, args.debounce)

    logger.info("Monitoring GPIO state...")

    try:
        while True:
            time.sleep(args.poll_interval)
    except KeyboardInterrupt:
        logger.info("Exiting program...")
    except RuntimeError as e:
        logger.error(f"Runtime error: {e}")
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio(gpio_ch)
        logger.info("GPIO cleanup complete.")
        logger.info("Automated GPIO control system stopped.")

if __name__ == "__main__":
    try:
        main()
    except RuntimeError as e:
        logger.error(f"Fatal error: {e}")
        sys.exit(1)
    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
        sys.exit(1)

