#!/usr/bin/env python3

"""
This module provides a class for controlling a robot arm using a Fuchikoma robotic arm library.
It incorporates comprehensive error handling, detailed documentation, and adheres to best practices.
"""

import time
import atexit
from typing import Optional, Callable

try:
    from Fuchikoma import Fuchikoma
except ImportError:
    print("Error: Fuchikoma library not found. Please install it using 'pip install Fuchikoma'.")
    exit(1)


class RobotArm:
    """
    A class to control a robot arm using the Fuchikoma library.
    """

    SERVO_MIN_PULSE = 150
    SERVO_MAX_PULSE = 600
    SERVO_FREQUENCY = 60  # Hz
    DEFAULT_DELAY = 0.029  # seconds
    MIN_ANGLE = -77
    MAX_ANGLE = 77

    def __init__(self, i2c_bus_number: int = 1, debug: bool = False):
        """
        Initializes the RobotArm object.

        Args:
            i2c_bus_number (int): The I2C bus number. Defaults to 1.
            debug (bool): Enable debug logging. Defaults to False.
        """
        self.i2c_bus_number = i2c_bus_number
        self.debug = debug
        self.pwm = None
        self.arm = None
        self.initialize_i2c()
        self.initialize_arm()
        self.atexit_cleanup()

    def initialize_i2c(self):
        """Initializes the I2C bus."""
        try:
            self.pwm = Fuchikoma.PCA9685(self.i2c_bus_number, debug=self.debug)
        except (ValueError, OSError) as e:
            print(f"Error initializing I2C: {e}")
            exit(1)

    def initialize_arm(self):
        """Initializes the Fuchikoma arm."""
        try:
            self.arm = Fuchikoma.Arm()
        except Exception as e:
            print(f"Error initializing arm: {e}")
            self.cleanup()  # Clean up on initialization failure
            exit(1)

    def atexit_cleanup(self):
        """Registers cleanup function to be called on exit."""
        atexit.register(self.cleanup)

    def cleanup(self):
        """Releases resources and performs cleanup."""
        if self.pwm:
            try:
                self.pwm.setPWM(0, 0, 0)  # De-initialize all channels
                self.pwm.setPWM(1, 0, 0)
                self.pwm.setPWM(2, 0, 0)
                self.pwm.setPWM(3, 0, 0)
                self.pwm.setPWM(4, 0, 0)
                self.pwm.setPWM(5, 0, 0)
                self.pwm.setPWM(6, 0, 0)
                self.pwm.setPWM(7, 0, 0)
                self.pwm.setPWM(8, 0, 0)
                self.pwm.setPWM(9, 0, 0)
                self.pwm.setPWM(10, 0, 0)
                self.pwm.setPWM(11, 0, 0)
                self.pwm.setPWM(12, 0, 0)
                self.pwm.setPWM(13, 0, 0)
                self.pwm.setPWM(14, 0, 0)
                self.pwm.setPWM(15, 0, 0)
                self.pwm.setPWM(16, 0, 0)
                self.pwm.setPWM(17, 0, 0)
                self.pwm.setPWM(18, 0, 0)
                self.pwm.setPWM(19, 0, 0)
                self.pwm.setPWM(20, 0, 0)
                self.pwm.setPWM(21, 0, 0)
                self.pwm.setPWM(22, 0, 0)
                self.pwm.setPWM(23, 0, 0)
            except Exception as e:
                print(f"Error during cleanup: {e}")
        if self.arm:
            try:
                self.arm.close()
            except Exception as e:
                print(f"Error closing arm: {e}")
        print("Cleanup complete.")

    def _validate_api(self, api_name: str):
        """Validates that the given API name exists."""
        if api_name not in self.arm.api:
            raise ValueError(f"Invalid API name: {api_name}.  Available APIs: {self.arm.api}")

    def _validate_angle(self, angle: float, api_name: str):
        """Validates that the given angle is within the allowed range."""
        if not self.MIN_ANGLE <= angle <= self.MAX_ANGLE:
            raise ValueError(f"Invalid angle for {api_name}. Angle must be between {self.MIN_ANGLE} and {self.MAX_ANGLE}.")

    def _calculate_pulse(self, angle: float) -> int:
        """Calculates the pulse width for a given angle."""
        zero_pulse = (self.SERVO_MIN_PULSE + self.SERVO_MAX_PULSE) / 2
        pulse_width = zero_pulse - self.SERVO_MIN_PULSE
        pulse = zero_pulse + (pulse_width * angle / self.MAX_ANGLE)
        return int(pulse)

    def move_servo(self, channel: int, angle: float, delay: float = DEFAULT_DELAY) -> None:
        """
        Moves a servo motor to a specified angle.

        Args:
            channel (int): The PWM channel (0-15) connected to the servo.
            angle (float): The desired angle in degrees.
            delay (float): The delay after setting the servo position (in seconds). Defaults to DEFAULT_DELAY.

        Raises:
            ValueError: If the channel is invalid or the angle is out of range.
        """
        self._validate_angle(angle, "servo")
        pulse = self._calculate_pulse(angle)
        try:
            self.pwm.setPWM(channel, 0, pulse)
            time.sleep(delay)
            self.pwm.setPWM(channel, 0, 0)  # De-energize the servo
        except Exception as e:
            print(f"Error moving servo on channel {channel}: {e}")

    def _move_servo_with_lock(self, channel: int, angle: float, lock_channel: int, lock_state: bool, delay: float = DEFAULT_DELAY) -> None:
        """Moves a servo and locks the other servo."""
        try:
            self.move_servo(channel, angle, delay)
            self.move_servo(lock_channel, 75 if lock_state else -75, delay)
        except Exception as e:
            print(f"Error moving servo with lock: {e}")

    def bite(self) -> None:
        """Closes the claw."""
        self._move_servo_with_lock(0, -75, 1, True)

    def open_claw(self) -> None:
        """Opens the claw."""
        self._move_servo_with_lock(0, 75, 1, False)

    def lock(self) -> None:
        """Locks the lock."""
        self._move_servo_with_lock(1, 75, 0, True)

    def unlock(self) -> None:
        """Unlocks the lock."""
        self._move_servo_with_lock(1, -75, 0, False)

    def shoot(self) -> None:
        """Activates the water gun."""
        self._move_servo_with_lock(2, -75, 0, True)
        time.sleep(0.15)
        self.load_water()

    def load_water(self) -> None:
        """Loads the water gun."""
        self._move_servo_with_lock(2, 75, 0, False)

    def move_forward(self, angle: float, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm forward."""
        self._move_servo_with_lock(3, angle, 4, True, delay)

    def move_backward(self, angle: float, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm backward."""
        self._move_servo_with_lock(3, -angle, 4, False, delay)

    def move_left(self, angle: float, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm left."""
        self._move_servo_with_lock(4, angle, 5, True, delay)

    def move_right(self, angle: float, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm right."""
        self._move_servo_with_lock(4, -angle, 5, False, delay)

    def move_up(self, angle: float, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm up."""
        self._move_servo_with_lock(5, angle, 6, True, delay)

    def move_down(self, angle: float, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm down."""
        self._move_servo_with_lock(5, -angle, 6, False, delay)

    def move_forward_with_lock(self, angle: float, lock_channel: int, lock_state: bool, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm forward and locks the other servo."""
        try:
            self.move_forward(angle, delay)
            self.move_servo(lock_channel, 75 if lock_state else -75, delay)
        except Exception as e:
            print(f"Error moving forward with lock: {e}")

    def move_backward_with_lock(self, angle: float, lock_channel: int, lock_state: bool, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm backward and locks the other servo."""
        try:
            self.move_backward(angle, delay)
            self.move_servo(lock_channel, 75 if lock_state else -75, delay)
        except Exception as e:
            print(f"Error moving backward with lock: {e}")

    def move_left_with_lock(self, angle: float, lock_channel: int, lock_state: bool, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm left and locks the other servo."""
        try:
            self.move_left(angle, delay)
            self.move_servo(lock_channel, 75 if lock_state else -75, delay)
        except Exception as e:
            print(f"Error moving left with lock: {e}")

    def move_right_with_lock(self, angle: float, lock_channel: int, lock_state: bool, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm right and locks the other servo."""
        try:
            self.move_right(angle, delay)
            self.move_servo(lock_channel, 75 if lock_state else -75, delay)
        except Exception as e:
            print(f"Error moving right with lock: {e}")

    def move_up_with_lock(self, angle: float, lock_channel: int, lock_state: bool, delay: float = DEFAULT_DELAY) -> None:
        """Moves the arm up and locks the other servo."""
        try:
            self.move_up(angle, delay)
            self.move_servo(lock_channel, 75 if lock_state else -75, delay)
