import RPi.GPIO as GPIO
import time
import random

# Define the GPIO pin connected to the LED
LED_PIN = 18

# Define the water quality threshold
WATER_QUALITY_THRESHOLD = 50

# Define the current limit for the LED resistor (330 Ohm)
LED_CURRENT_LIMIT = 0.033  # Amps

# Define the number of readings to simulate
NUM_READINGS = 5

# Define the delay between readings (2 seconds)
READING_DELAY = 2

# Define the probability of a sensor read failure (10%)
SENSOR_FAILURE_PROBABILITY = 0.1

def setup_gpio(pin):
    """Sets up the GPIO pin for the LED."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT)
        print("GPIO setup complete.")
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        return False
    return True

def read_water_quality():
    """Simulates reading water quality data."""
    try:
        # Simulate reading from a sensor
        water_quality = random.randint(0, 100)
        return water_quality
    except Exception as e:
        print(f"Error reading water quality: {e}")
        return None

def control_led(pin, water_quality, threshold):
    """Controls the LED based on water quality."""
    try:
        if water_quality is not None:
            if water_quality < threshold:
                GPIO.output(pin, GPIO.HIGH)  # Turn LED on
                print("LED ON: Water quality below threshold.")
            else:
                GPIO.output(pin, GPIO.LOW)  # Turn LED off
                print("LED OFF: Water quality above threshold.")
        else:
            print("No water quality data available.")
    except Exception as e:
        print(f"Error controlling LED: {e}")

def main():
    """Main function to run the water quality monitoring system."""
    if not setup_gpio(LED_PIN):
        print("Failed to setup GPIO. Exiting.")
        return

    try:
        for i in range(NUM_READINGS):
            water_quality = read_water_quality()

            if water_quality is not None:
                # Simulate sensor read failure with a probability
                if random.random() < SENSOR_FAILURE_PROBABILITY:
                    print(f"Warning: Simulated sensor read failure at reading {i+1}.")
                    water_quality = None  # Indicate failure

                if water_quality is not None:
                    print(f"Reading {i+1}: Water Quality = {water_quality}%")
                    control_led(LED_PIN, water_quality, WATER_QUALITY_THRESHOLD)
            else:
                print(f"Error: Failed to read water quality at reading {i+1}.")

            time.sleep(READING_DELAY)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

