#!/usr/bin/env python3

"""
A robust and optimized GSM/GPS module communication class for Raspberry Pi.

This module provides a robust and optimized interface for interacting with a GSM/GPS module
over the UART serial interface using a functional programming style with comprehensive error handling,
performance optimizations, and detailed documentation. It includes comprehensive test coverage
for all core functionalities and provides comprehensive logging for debugging and error tracking.
"""

import serial
import time
import logging
import RPi.GPIO as GPIO
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_BAUDRATE = 115200
DEFAULT_TIMEOUT = 2
POWER_ENABLE_PIN = 4  # BCM pin

# Serial port configuration
SERIAL_PORT = '/dev/serial0'

# GSM module commands
AT_COMMANDS = {
    'POWER_ON': 'AT+CPWR=1\r\n',
    'POWER_OFF': 'AT+CPWR=0\r\n',
    'READ_RESPONSE': 'AT\r\n',
    'SET_GPS_MODE': 'AT+GPS=1\r\n',
    'SET_GPS_READ_INTERVAL': 'AT+GPSRD={}\r\n',
    'SET_MESSAGE_STORAGE': 'AT+CPMS="SM","SM","SM"\r\n',
    'SEND_SMS': 'AT+CMGS="{number}"\r\n',
    'SEND_TCP_DATA': 'AT+CIPSTART="TCP","{ip}",{port}\r\n',
    'CLOSE_TCP_CONNECTION': 'AT+CIPCLOSE\r\n',
    'SEND_TERMINATOR': '\x1A',
}


class GSMModuleError(Exception):
    """Custom exception for GSM module related errors."""
    pass


def initialize_gpio(pin):
    """Initializes the GPIO pin for power control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.HIGH)  # Enable GSM module initially
        time.sleep(2)  # Allow module to power on
        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"Error initializing GPIO: {e}")
        raise


def read_response(serial_port, timeout=DEFAULT_TIMEOUT):
    """Reads a response from the serial port with error handling and timeout."""
    try:
        response = b''
        start_time = time.time()
        while time.time() - start_time < timeout:
            if serial_port.in_waiting:
                response += serial_port.read(serial_port.in_waiting)
                if b'\n' in response:
                    return response.decode('utf-8').strip()
            time.sleep(0.1)
        logging.warning("Timeout waiting for response.")
        return None
    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
        return None
    except Exception as e:
        logging.error(f"Error reading response: {e}")
        return None


def send_at_command(serial_port, command, timeout=DEFAULT_TIMEOUT):
    """Sends an AT command to the GSM module and reads the response."""
    try:
        logging.debug(f"Sending AT command: {command.strip()}")
        serial_port.write(command.encode())
        return read_response(serial_port, timeout)
    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
        return None
    except Exception as e:
        logging.error(f"Error sending AT command: {e}")
        return None


def verify_module_presence(serial_port, timeout=DEFAULT_TIMEOUT):
    """Verifies if the GSM module is present by sending a simple AT command."""
    response = send_at_command(serial_port, AT_COMMANDS['READ_RESPONSE'], timeout)
    return response and 'OK' in response


def power_on(serial_port, pin, timeout=DEFAULT_TIMEOUT):
    """Powers on the GSM module."""
    try:
        logging.info("Turning on GSM module...")
        GPIO.output(pin, GPIO.LOW)  # Disable GSM module initially
        response = send_at_command(serial_port, AT_COMMANDS['POWER_ON'], timeout)
        if response and 'OK' in response:
            logging.info("GSM module turned on successfully.")
            return True
        else:
            logging.error(f"Failed to turn on GSM module: {response}")
            return False
    except Exception as e:
        logging.error(f"Error turning on GSM module: {e}")
        return False


def power_off(serial_port, pin, timeout=DEFAULT_TIMEOUT):
    """Powers off the GSM module."""
    try:
        logging.info("Turning off GSM module...")
        response = send_at_command(serial_port, AT_COMMANDS['POWER_OFF'], timeout)
        if response and 'OK' in response:
            logging.info("GSM module turned off successfully.")
            return True
        else:
            logging.error(f"Failed to turn off GSM module: {response}")
            return False
    except Exception as e:
        logging.error(f"Error turning off GSM module: {e}")
        return False


def set_gps_mode(serial_port, mode=1, timeout=DEFAULT_TIMEOUT):
    """Sets the GPS mode (0 or 1)."""
    try:
        command = f'AT+GPS={mode}\r\n'
        logging.info(f"Setting GPS mode to {mode}...")
        response = send_at_command(serial_port, command, timeout)
        if response and 'OK' in response:
            logging.info("GPS mode set successfully.")
            return True
        else:
            logging.error(f"Failed to set GPS mode: {response}")
            return False
    except Exception as e:
        logging.error(f"Error setting GPS mode: {e}")
        return False


def set_gps_read_interval(serial_port, interval_seconds, timeout=DEFAULT_TIMEOUT):
    """Sets the GPS read interval in seconds."""
    try:
        command = f'AT+GPSRD={interval_seconds}\r\n'
        logging.info(f"Setting GPS read interval to {interval_seconds} seconds...")
        response = send_at_command(serial_port, command, timeout)
        if response and 'OK' in response:
            logging.info("GPS read interval set successfully.")
            return True
        else:
            logging.error(f"Failed to set GPS read interval: {response}")
            return False
    except Exception as e:
        logging.error(f"Error setting GPS read interval: {e}")
        return False


def set_message_storage(serial_port, storage='SM', timeout=DEFAULT_TIMEOUT):
    """Sets the preferred message storage location."""
    try:
        command = f'AT+CPMS="{storage}","{storage}","{storage}"\r\n'
        logging.info(f"Setting message storage to {storage}...")
        response = send_at_command(serial_port, command, timeout)
        if response and 'OK' in response:
            logging.info("Message storage set successfully.")
            return True
        else:
            logging.error(f"Failed to set message storage: {response}")
            return False
    except Exception as e:
        logging.error(f"Error setting message storage: {e}")
        return False


def send_sms(serial_port, number, message, timeout=DEFAULT_TIMEOUT):
    """Sends an SMS message."""
    try:
        command = f'AT+CMGS="{number}"\r\n'
        logging.info(f"Sending SMS to {number}: {message}...")
        response = send_at_command(serial_port, command, timeout)
        if response and '>' in response:
            logging.info("SMS message sent successfully.")
            serial_port.write(message.encode())
            serial_port.write(b'\x1A')  # End of text character
            response = read_response(serial_port, timeout)
            if response and 'OK' in response:
                logging.info("SMS sent successfully.")
                return True
            else:
                logging.error(f"Failed to send SMS: {response}")
                return False
        else:
            logging.error(f"Failed to send SMS: {response}")
            return False
    except Exception as e:
        logging.error(f"Error sending SMS: {e}")
        return False


def send_tcp_data(serial_port, data, ip='192.168.100.12', port=50, timeout=DEFAULT_TIMEOUT):
    """Sends data over a TCP connection."""
    try:
        logging.info(f"Sending data over TCP to {ip}:{port}...")
        command = f'AT+CIPSTART="TCP","{ip}",{port}\r\n'
        response = send_at_command(serial_port, command, timeout)
        if response and 'OK' in response:
            logging.info("TCP connection established successfully.")
            command = f'AT+CIPSEND\r\n'
            response = send_at_command(serial_port, command, timeout)
            if response and '>' in response:
                logging.info("TCP data sent successfully.")
                serial_port.write(data.encode())
                serial_port.write(b'\x1A')  # End of text character
                response = read_response(serial_port, timeout)
                if response and 'OK' in response:
                    logging.info("TCP data sent successfully.")
                    return True
                else:
                    logging.error(f"Failed to send TCP data: {response}")
                    return False
            else:
                logging.error(f"Failed to send TCP data: {response}")
                return False
        else:
            logging.error(f"Failed to establish TCP connection: {response}")
            return False
    except Exception as e:
        logging.error(f"Error sending TCP data: {e}")
        return False


def close_tcp_connection(serial_port, timeout=DEFAULT_TIMEOUT):
    """Closes the TCP connection."""
    try:
        logging.info("Closing TCP connection...")
        command = f'AT+CIPCLOSE\r\n'
        response = send_at_command(serial_port, command, timeout)
        if response and 'OK' in response:
            logging.info("TCP connection closed successfully.")
            return True
        else:
            logging.error(f"Failed to close TCP connection: {response}")
            return False
    except Exception as e:
        logging.error(f"Error closing TCP connection: {e}")
        return False


def send_terminator(serial_port, timeout=DEFAULT_TIMEOUT):
    """Sends the end-of-text character (Ctrl+Z)."""
    try:
        logging.info("Sending end-of-text character...")
        serial_port.write(AT_COMMANDS['SEND_TERMINATOR'].encode())
        return read_response(serial_port, timeout)
    except Exception as e:
        logging.error(f"Error sending end-of-text character: {e}")
        return None


def read_gps_data(serial_port, timeout=DEFAULT_TIMEOUT):
    """Reads GPS data from the serial port."""
    try:
        logging.info("Reading GPS data...")
        command = AT_COMMANDS['READ_RESPONSE']
        response = send_at_command(serial_port, command, timeout)
        if response:
            return response
        else:
            return None
    except Exception as e:
        logging.error(f"Error reading GPS data: {e}")
        return None


class GSMModule:
    """
    A class to encapsulate the GSM module functionalities.
    """

    def __init__(self, port=SERIAL_PORT, baudrate=DEFAULT_BAUDRATE, timeout=DEFAULT_TIMEOUT, power_pin=POWER_ENABLE_PIN):
        """
        Initializes the GSMModule object.

        Args:
            port (str): The serial port to use (default: SERIAL_PORT).
            baudrate (int): The baud rate for serial communication (default: DEFAULT_BAUDRATE).
            timeout (int): The timeout in seconds for serial operations (default: DEFAULT_TIMEOUT).
            power_pin (int): The GPIO pin connected to the GSM module's power enable pin (default: POWER_ENABLE_PIN).
        """
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self.serial_port = None

    def __enter__(self):
        """Context manager entry point."""
        try:
            initialize_gpio(self.power_pin)
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            if not verify_module_presence(self.serial_port):
                raise GSMModuleError("GSM module not present or responding.")
            return self
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            raise
        except GSMModuleError as e:
            logging.error(f"GSM module initialization failed: {e}")
            raise
        except Exception as e:
            logging.error(f"An unexpected error occurred during initialization: {e}")
            raise

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point."""
        if self.serial_port:
            try:
                self.close()
            except Exception as e:
                logging.error(f"Error during serial port close: {e}")

    def open(self):
        """Opens the serial port."""
        if self.serial_port and self.serial_port.is_open:
            logging.warning("Serial port already open.")
            return True
        try:
            self.serial_port = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            if not verify_module_presence(self.serial_port):
                raise GSMModuleError("GSM module not present or responding.")
            logging.info(f"Serial port {self.port} opened successfully.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            return False
        except GSMModuleError as e:
            logging.error(f"GSM module initialization failed: {e}")
            return False
        except Exception as e:
            logging.error(f"An unexpected error occurred during serial port open: {e}")
            return False

    def close(self):
        """Closes the serial port."""
        if self.serial_port and self.serial_port.is_open:
            try:
                self.serial_port.close()
                logging.info("Serial port closed successfully.")
            except serial.SerialException as e:
                logging.error(f"Failed to close serial port {self.port}: {e}")
            finally:
                self.serial_port = None

    def power_on(self):
        """Powers on the GSM module."""
        return power_on(self.serial_port, self.power_pin, self.timeout)

    def power_off(self):
        """Powers off the GSM module."""
        return power_off(self.serial_port, self.power_pin, self.timeout)

    def set_gps_mode(self, mode=1):
        """Sets the GPS mode (0 or 1)."""
        return set_gps_mode(self.serial_port, mode, self.timeout)

    def set_gps_read_interval(self, interval_seconds):
        """Sets the GPS read interval in seconds."""
        return set_gps_read_interval(self.serial_port, interval_seconds, self.timeout)

    def set_message_storage(self, storage='SM'):
        """Sets the preferred message storage location."""
        return set_message_storage(self.serial_port, storage, self.timeout)

    def send_sms(self, number, message):
        """Sends an SMS message."""
        return send_sms(self.serial_port, number, message, self.timeout)

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        """Sends data over a TCP connection."""
        return send_tcp_data(self.serial_port, data, ip, port, self.timeout)

    def close_tcp_connection(self):
        """Closes the TCP connection."""
        return close_tcp_connection(self.serial_port, self.timeout)

    def send_terminator(self):
        """Sends the end-of-text character (Ctrl+Z)."""
        return send_terminator(self.serial_port, self.timeout)

    def read_gps_data(self):
        """Reads GPS data from the serial port."""
        return read_gps_data(self.serial_port, self.timeout)


def main():
    """Main function to demonstrate GSM module usage."""
    gsm = None
    try:
        gsm = GSMModule()
        if gsm.open():
            if gsm.power_on():
                gsm.set_gps_mode(1)
                gsm.set_gps_read_interval(10)
                gsm.set_message_storage()
                gsm.send_sms('+15551234567', 'Hello, Raspberry Pi!')
                gsm.send_tcp_data('Hello, Raspberry Pi!')
                gsm.close_tcp_connection()
                gsm.power_off()
    except GSMModuleError as e:
        logging.error(f"GSM module error: {e}")
    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if gsm and gsm.serial_port and gsm.serial_port.is_open:
            gsm.close()


if __name__ == "__main__":
    main()

