def send_tcp_data(serial_port, data, ip='192.168.100.12', port=50, timeout=DEFAULT_TIMEOUT):
    """Sends data over a TCP connection."""
    try:
        logging.info(f"Sending data over TCP to {ip}:{port}...")
        command = f'AT+CIPSTART="TCP","{ip}",{port}\r\n'
        response = send_at_command(serial_port, command, timeout)
        if response and 'OK' in response:
            logging.info("TCP connection established successfully.")
            command = f'AT+CIPSEND\r\n'
            response = send_at_command(serial_port, command, timeout)
            if response and '>' in response:
                logging.info("TCP data sent successfully.")
                serial_port.write(data.encode())
                serial_port.write(b'\x1A')  # End of text character
                response = read_response(serial_port, timeout)
                if response and 'OK' in response:
                    logging.info("TCP data sent successfully.")
                    return True
                else:
                    logging.error(f"Failed to send TCP data: {response}")
                    return False
            else:
                logging.error(f"Failed to send TCP data: {response}")
                return False
        else:
            logging.error(f"Failed to establish TCP connection: {response}")
            return False
    except Exception as e:
        logging.error(f"Error sending TCP data: {e}")
        return False


def close_tcp_connection(serial_port, timeout=DEFAULT_TIMEOUT):
    """Closes the TCP connection."""
    try:
        logging.info("Closing TCP connection...")
        command = f'AT+CIPCLOSE\r\n'
        response = send_at_command(serial_port, command, timeout)
        if response and 'OK' in response:
            logging.info("TCP connection closed successfully.")
            return True
        else:
            logging.error(f"Failed to close TCP connection: {response}")
            return False
    except Exception as e:
