        return read_response(serial_port, timeout)
    except Exception as e:
        logging.error(f"Error sending end-of-text character: {e}")
        return None


def read_gps_data(serial_port, timeout=DEFAULT_TIMEOUT):
    """Reads GPS data from the serial port."""
    try:
