        command = AT_COMMANDS['READ_RESPONSE']
        response = send_at_command(serial_port, command, timeout)
        if response:
            return response
        else:
            return None
    except Exception as e:
        logging.error(f"Error reading GPS data: {e}")
        return None


class GSMModule:
    """
    A class to encapsulate the GSM module functionalities.
    """

    def __init__(self, port=SERIAL_PORT, baudrate=DEFAULT_BAUDRATE, timeout=DEFAULT_TIMEOUT, power_pin=POWER_ENABLE_PIN):
        """
        Initializes the GSMModule object.

        Args:
            port (str): The serial port to use (default: SERIAL_PORT).
            baudrate (int): The baud rate for serial communication (default: DEFAULT_BAUDRATE).
            timeout (int): The timeout in seconds for serial operations (default: DEFAULT_TIMEOUT).
            power_pin (int): The GPIO pin connected to the GSM module's power enable pin (default: POWER_ENABLE_PIN).
