                gsm.power_off()
    except GSMModuleError as e:
        logging.error(f"GSM module error: {e}")
    except serial.SerialException as e:
        logging.error(f"Serial port error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if gsm and gsm.serial_port and gsm.serial_port.is_open:
            gsm.close()


