import RPi.GPIO as GPIO
import time
import logging

# Configure logging for the smart agriculture system
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# GPIO pin assignments for the nutrient pump and grow light
PUMP_PIN = 20
LIGHT_PIN = 21

# Intent keywords for the smart agriculture system
INTENT_KEYWORDS = {
    "pump_on": "pump_on",
    "pump_off": "pump_off",
    "light_toggle": "light_toggle",
}


def initialize_actuators():
    """Initializes the GPIO pins for the nutrient pump and grow light."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT)
        GPIO.setup(LIGHT_PIN, GPIO.OUT)
        GPIO.output(PUMP_PIN, GPIO.LOW)  # Ensure pump is initially off
        GPIO.output(LIGHT_PIN, GPIO.LOW)  # Ensure light is initially off
        logging.info("Actuators initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize actuators: {e}")
        raise


def parse_intent(phrase):
    """Parses a phrase into an intent keyword."""
    for keyword, intent in INTENT_KEYWORDS.items():
        if keyword.lower() in phrase.lower():
            return intent
    return "unknown"


def control_pump(intent):
    """Controls the nutrient pump based on the given intent."""
    if intent == "pump_on":
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        logging.info("Nutrient pump turned ON.")
    elif intent == "pump_off":
        GPIO.output(PUMP_PIN, GPIO.LOW)
        logging.info("Nutrient pump turned OFF.")
    else:
        logging.warning(f"Unknown pump intent: {intent}")


def control_light(intent):
    """Controls the grow light based on the given intent."""
    if intent == "light_toggle":
        GPIO.output(LIGHT_PIN, GPIO.HIGH if GPIO.input(LIGHT_PIN) == GPIO.LOW else GPIO.LOW)
        logging.info("Grow light toggled.")
    else:
        logging.warning(f"Unknown light intent: {intent}")


def main():
    """Main function to run the smart agriculture system."""
    try:
        initialize_actuators()
        phrases = [
            "turn the pump on",
            "switch the light",
            "turn pump off",
            "unknown command",
        ]

        for phrase in phrases:
            intent = parse_intent(phrase)
            logging.info(f"Parsed phrase: {phrase}, Intent: {intent}")

            if intent != "unknown":
                control_pump(intent)
                control_light(intent)
            else:
                logging.warning(f"Unknown intent in phrase: {phrase}")

    except KeyboardInterrupt:
        logging.info("Script interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.output(PUMP_PIN, GPIO.LOW)  # Ensure pump is off on exit
        GPIO.output(LIGHT_PIN, GPIO.LOW)  # Ensure light is off on exit
        GPIO.cleanup()  # Clean up GPIO pins
        logging.info("Actuators cleaned up. Exiting.")


if __name__ == "__main__":
    main()

