import threading
import logging
import signal
import sys
from typing import List, Dict, Any, Optional

import serial
from flask import Flask, Response, request, jsonify, abort

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Flask application
app = Flask(__name__)

# Global lock for thread safety
lock = threading.Lock()

# Instrument data store
instrument_data: List[Dict[str, Any]] = [{"id": 1, "name": "Instrument 1", "done": False}, {"id": 2, "name": "Instrument 2", "done": False}]

# UART port configuration
UART_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

# Global UART port object
uart_port: Optional[serial.Serial] = None

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info("Shutting down gracefully...")
    if uart_port and uart_port.is_open:
        uart_port.close()
        logging.info("UART port closed.")
    sys.exit(0)

# Register the signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Context manager for UART port opening and closing
def with_uart_port(func):
    """Context manager for UART port opening and closing."""
    def wrapper(*args, **kwargs):
        global uart_port
        try:
            if uart_port is None or not uart_port.is_open:
                uart_port = serial.Serial(UART_PORT, BAUD_RATE, timeout=TIMEOUT)
                logging.info(f"Opened UART port {UART_PORT}")
            return func(*args, **kwargs)
        except serial.SerialException as e:
            logging.error(f"Error opening UART port: {e}")
            return Response("Error opening UART port", status=500, mimetype='text/plain')
        finally:
            if uart_port and uart_port.is_open:
                uart_port.close()
                logging.info("UART port closed.")
    return wrapper

# API endpoint for getting instrument data
@app.route("/data", methods=["GET"])
def get_instrument_data():
    """Returns a list of instrument data."""
    with lock:
        return jsonify(instrument_data), 200

# API endpoint for getting a specific instrument
@app.route("/data/<int:item_id>", methods=["GET"])
def get_instrument(item_id: int):
    """Returns a specific instrument by ID."""
    with lock:
        item = next((item for item in instrument_data if item["id"] == item_id), None)
        if item:
            return jsonify(item), 200
        else:
            return Response("Item not found", status=404, mimetype='text/plain')

# API endpoint for creating an instrument
@app.route("/data", methods=["POST"])
def create_instrument():
    """Creates a new instrument."""
    try:
        data = request.get_json()
        if not data or "name" not in data or not data["name"]:
            return Response("Invalid request: Missing name field", status=400, mimetype='text/plain')

        with lock:
            new_id = max(item["id"] for item in instrument_data) + 1
            new_item = {"id": new_id, "name": data["name"], "done": False}
            instrument_data.append(new_item)
            return jsonify(new_item), 201, {"Location": f"/data/{new_id}"}
    except (KeyError, TypeError) as e:
        logging.error(f"Error creating instrument: {e}")
        return Response(f"Invalid request: {e}", status=400, mimetype='text/plain')

# API endpoint for sending a command to the instrument
@app.route("/version", methods=["GET"])
@with_uart_port
def get_instrument_version():
    """Sends a command to the instrument and returns the version."""
    try:
        if uart_port is None:
            return Response("UART port not initialized", status=500, mimetype='text/plain')

        uart_port.write(b"*IDN?\n")
        response = uart_port.readline().decode('ascii', errors='replace').strip()
        return Response(response, mimetype='text/plain')
    except serial.SerialException as e:
        logging.error(f"Error communicating with UART: {e}")
        return Response(f"Error communicating with UART: {e}", status=500, mimetype='text/plain')
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        return Response(f"An unexpected error occurred: {e}", status=500, mimetype='text/plain')

# Main function
def main():
    """Main function to start the Flask web service."""
    try:
        app.run(debug=False, host='0.0.0.0', port=5000)
    except Exception as e:
        logging.error(f"Failed to start Flask app: {e}")
        if uart_port and uart_port.is_open:
            uart_port.close()
            logging.info("UART port closed.")
        sys.exit(1)

# Run the main function
if __name__ == "__main__":
    main()

